import { useEffect, useRef, useState } from "react";
import { api, type Waveform } from "@/lib/ipc";
import { awaitJob } from "@/services/jobs";

/**
 * Timeline waveform for an audio clip — peaks are generated by the
 * `audio.waveform` job (async, disk-cached by content hash) and drawn for
 * the clip's [sourceInMs, +durationMs) window. ~1 bucket per rendered px;
 * zooming re-requests a finer bucket count.
 */
export function WaveformCanvas({
  srcPath,
  sourceInMs,
  durationMs,
  heightPx,
  widthPx,
}: {
  srcPath: string;
  sourceInMs: number;
  durationMs: number;
  heightPx: number;
  widthPx: number;
}) {
  const [wf, setWf] = useState<Waveform | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const buckets = Math.max(16, Math.min(64000, Math.round(widthPx)));

  useEffect(() => {
    let live = true;
    (async () => {
      try {
        let w = await api.readWaveform(srcPath, buckets);
        if (!w) {
          const jobId = await api.generateWaveform(srcPath, buckets);
          if (jobId) {
            await awaitJob(jobId);
            w = await api.readWaveform(srcPath, buckets);
          }
        }
        if (live) setWf(w);
      } catch {
        /* missing/undecodable source — waveform simply absent */
      }
    })();
    return () => {
      live = false;
    };
  }, [srcPath, buckets]);

  useEffect(() => {
    const cv = canvasRef.current;
    if (!cv || !wf || wf.buckets === 0) return;
    const g = cv.getContext("2d");
    if (!g) return;
    const W = cv.width;
    const H = cv.height;
    g.clearRect(0, 0, W, H);
    g.fillStyle = "rgba(56, 189, 248, 0.55)";
    const mid = H / 2;
    const b0 = Math.floor((sourceInMs / Math.max(1, wf.durationMs)) * wf.buckets);
    const b1 = Math.ceil(((sourceInMs + durationMs) / Math.max(1, wf.durationMs)) * wf.buckets);
    const span = Math.max(1, b1 - b0);
    for (let x = 0; x < W; x++) {
      const b = Math.min(wf.buckets - 1, Math.max(0, b0 + Math.floor((x / W) * span)));
      const lo = wf.peaks[b * 2] ?? 0;
      const hi = wf.peaks[b * 2 + 1] ?? 0;
      const y0 = mid - hi * mid;
      const y1 = mid - lo * mid;
      g.fillRect(x, Math.min(y0, y1), 1, Math.max(1, Math.abs(y1 - y0)));
    }
  }, [wf, sourceInMs, durationMs, widthPx, heightPx]);

  return (
    <canvas
      ref={canvasRef}
      width={Math.max(2, Math.min(8192, Math.round(widthPx)))}
      height={Math.max(2, Math.round(heightPx))}
      className="pointer-events-none absolute inset-0 h-full w-full opacity-80"
    />
  );
}
